"""Same-new-header SOURCE32 control; source implementation untouched."""
import argparse,hashlib,json,shutil
from pathlib import Path
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--parent',type=Path,required=True);p.add_argument('--candidate',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);shutil.copytree(a.parent/'source',a.output/'source');shutil.copytree(a.candidate/'headers',a.output/'headers');oldfiles={str(x.relative_to(a.parent/'source')):sha(x)for x in(a.parent/'source').rglob('*')if x.is_file()};newfiles={str(x.relative_to(a.output/'source')):sha(x)for x in(a.output/'source').rglob('*')if x.is_file()};assert oldfiles==newfiles;headerfiles={str(x.relative_to(a.candidate/'headers')):sha(x)for x in(a.candidate/'headers').rglob('*')if x.is_file()};assert headerfiles=={str(x.relative_to(a.output/'headers')):sha(x)for x in(a.output/'headers').rglob('*')if x.is_file()};result=dict(status='SOURCE_ONLY_SAME_VOPT34_HEADER_PARENT32_IMPLEMENTATION_CONTROL',hardware_accessed=False,firmware_eligible=False,parent=str(a.parent.resolve()),candidate=str(a.candidate.resolve()),source_files_identical=oldfiles,header_files_identical=headerfiles,limits='Controlsourceonly; all58unitsmustcompileagainstnewICembedding beforecomparison. No VOPTbehavior/controlruntime.');(a.output/'result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':result['status'],'source_files':len(oldfiles),'header_files':len(headerfiles)},indent=2))
if __name__=='__main__':main()
